"""Test harness: run main.py on constructed envelopes."""
import json, subprocess, sys, hashlib

MAIN = '/app/submission/main.py'

def run(env_or_raw):
    if isinstance(env_or_raw, (dict, list)):
        raw = json.dumps(env_or_raw).encode()
    else:
        raw = env_or_raw if isinstance(env_or_raw, bytes) else env_or_raw.encode()
    p = subprocess.run([sys.executable, '-I', '-B', MAIN], input=raw,
                       capture_output=True, timeout=60)
    return p.returncode, p.stdout, p.stderr

def base_config(accounts=None, peers=None, ttl=1000, cap=10):
    accounts = accounts if accounts is not None else [
        {"id": "alice", "default": "sip:alice@lab.test",
         "aliases": ["sip:alice@lab.test", "sip:desk@lab.test", "tel:+12025550100"]},
        {"id": "bob", "default": "sip:bob@lab.test",
         "aliases": ["sip:bob@lab.test"]},
    ]
    peers = peers if peers is not None else [
        {"id": "edge", "mode": "access", "accounts": []},
        {"id": "trunk", "mode": "relay", "accounts": ["alice", "bob"]},
    ]
    return {"accounts": accounts, "peers": peers, "ttl_ms": ttl, "capacity": cap}

def envelope(events, config=None, version=1):
    cfg = base_config() if config is None else config
    return {"version": version, "config": cfg, "events": events}

def ev(t, peer, auth, egress, wire, ):
    return {"t": t, "peer": peer, "auth": auth, "egress": egress, "wire_hex": wire}

def h(s):
    if isinstance(s, str):
        s = s.encode('latin-1')
    return s.hex()

def req(method="MESSAGE", uri="sip:bob@lab.test", headers=None, body=b"",
        sep="\r\n", eol="\r\n", startline=None):
    """Build a request string. headers: list of (name, value) or raw strings."""
    if startline is None:
        startline = f"{method} {uri} SIP/2.0"
    lines = [startline]
    for hd in (headers or []):
        if isinstance(hd, str):
            lines.append(hd)
        else:
            lines.append(f"{hd[0]}:{hd[1]}")
    return sep.join(lines) + eol + sep + sep.join([]) + ("\r\n" if True else "") + body.decode('latin-1') if False else sep.join(lines) + eol + sep + sep + body.decode('latin-1')

def mkreq(method="MESSAGE", uri="sip:bob@lab.test", headers=None, body=b"",
          term="\r\n", startline=None, raw_headers=None):
    """headers: list of strings (full lines, no CRLF) or (name,value) tuples."""
    if startline is None:
        startline = f"{method} {uri} SIP/2.0"
    lines = [startline]
    for hd in (headers or []):
        if isinstance(hd, tuple):
            lines.append(f"{hd[0]}: {hd[1]}")
        else:
            lines.append(hd)
    text = "\r\n".join(lines) + "\r\n\r\n"
    return text.encode('latin-1') + (body if isinstance(body, bytes) else body.encode('latin-1'))

def std_headers(tag="t", frm="sip:alice@lab.test", to="sip:bob@lab.test",
                cid="demo", cseq="7 MESSAGE", cl=None, body=b""):
    hs = [("From", f"{frm};tag={tag}"), ("To", to), ("Call-ID", cid),
          ("CSeq", cseq)]
    if cl is None:
        cl = str(len(body))
    hs.append(("Content-Length", cl))
    return hs

def sha(b):
    return hashlib.sha256(b).hexdigest()

def expect(name, cond, extra=""):
    if cond:
        print(f"PASS {name}")
    else:
        print(f"FAIL {name} {extra}")
        globals()['FAILS'] = globals().get('FAILS', 0) + 1

FAILS = 0
def summary():
    print("FAILURES:", globals().get('FAILS', 0))
    return globals().get('FAILS', 0)
